on conflict (id) do update set name = excluded.name, address = excluded.address, plus_code = excluded.plus_code, latitude = excluded.latitude, longitude = excluded.longitude, smart_phone = excluded.smart_phone, globe_phone = excluded.globe_phone, google_review_url = excluded.google_review_url, is_google_business_verified = excluded.is_google_business_verified;

on conflict (id) do update set name = excluded.name, category = excluded.category, short_description = excluded.short_description, long_description = excluded.long_description, default_duration_minutes = excluded.default_duration_minutes, is_active = excluded.is_active, is_featured = excluded.is_featured;

select b.id, s.id from public.branches b cross join public.services s
on conflict (branch_id, service_id) do update set is_available = true;

select id, weekday, '08:00', '20:00', 30, 1
from public.branches cross join generate_series(1, 6) as weekday
on conflict (branch_id, staff_id, weekday) do update set open_time = excluded.open_time, close_time = excluded.close_time, slot_interval_minutes = excluded.slot_interval_minutes, capacity = excluded.capacity, is_active = true;

on conflict (key) do update set value = excluded.value;
